## Distributed Sliding-Window Rate Limiting with Redis

Fixed-window rate limiters suffer from burst spikes around window reset boundaries. Implementing sliding-window log algorithms in Redis tracks exact request timestamps per IP address to provide smooth traffic control.

```typescript
import Redis from "ioredis";
import { Request, Response, NextFunction } from "express";

const redis = new Redis(process.env.REDIS_URL!);

export function rateLimiter(maxRequests = 100, windowSeconds = 60) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const ip = req.ip || req.headers["x-forwarded-for"] || "unknown";
    const key = `rate_limit:${ip}`;
    const now = Date.now();
    const windowStart = now - windowSeconds * 1000;

    // Remove expired entries & add current request
    const pipeline = redis.pipeline();
    pipeline.zremrangebyscore(key, 0, windowStart);
    pipeline.zadd(key, now, now.toString());
    pipeline.zcard(key);
    pipeline.expire(key, windowSeconds);

    const results = await pipeline.exec();
    const requestCount = results?.[2]?.[1] as number;

    if (requestCount > maxRequests) {
      return res.status(429).json({ error: "Too many requests. Please try again later." });
    }

    next();
  };
}
```

